mapper.select:
SELECT * FROM notify_reminders
WHERE status = 'pending' AND remind_at <= #{now}
ORDER BY remind_at ASC LIMIT #{limit}
FOR UPDATE SKIP LOCKED

mapper.update:
UPDATE notify_reminders
SET status = 'processing', claimed_at = #{claimedAt}, attempt_count = #{attemptCount}
WHERE id = #{id}

UPDATE notify_reminders
SET status = #{status}, remind_at = #{remindAt}, claimed_at = #{claimedAt}
WHERE id = #{id}

UPDATE notify_reminders
SET status = 'sent', sent_at = #{deliveredAt}
WHERE user_id = #{userId} AND reminder_key = #{reminderKey}
  AND occurrence_key = #{occurrenceKey}
  AND status IN ('pending', 'processing', 'failed')
